  WriteResults results;
  // validate write batch size
  if (docs.size() > kMaxWriteBatchSize) {
    CHECK_RETURN_STATUS_EXPECTED(Status::InvalidArgument(
        "Too many docs: ", docs.size(), " exceeds max write batch size of ",
        kMaxWriteBatchSize));
