  for (auto &&doc : docs) {
    if (need_switch_to_new_segment()) {
      auto s = switch_to_new_segment_for_writing();
      CHECK_RETURN_STATUS_EXPECTED(s);
    }

    Status s;

    switch (mode) {
      case WriteMode::UPSERT:
        s = handle_upsert(doc);
        break;
      case WriteMode::UPDATE:
        s = handle_update(doc);
        break;
      case WriteMode::INSERT:
        s = handle_insert(doc);
